package com.thangit.boardinghouse.service;

import static com.thangit.boardinghouse.service.MonthlyBillingService.*;
import com.thangit.boardinghouse.common.exception.AuthException;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.dto.request.invoice.AdminInvoiceRequests.SaveInvoice;
import com.thangit.boardinghouse.dto.request.lifecycle.RentalLifecycleRequests.*;
import com.thangit.boardinghouse.dto.response.lifecycle.RentalLifecycleResponses.Created;
import com.thangit.boardinghouse.repository.RentalLifecycleRepository;
import com.thangit.boardinghouse.security.AuthenticatedUser;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Operational handover, immutable financial approvals and actual cash are separate events. */
@Service
public class CheckoutSettlementService {
    public record Schedule(@NotNull LocalDate date,@NotNull @Min(0) Long version,@NotBlank @Size(max=1000) String reason,@NotBlank @Size(max=500) String reference) {}
    public record VersionedReason(@NotNull @Min(0) Long version,@NotBlank @Size(max=1000) String reason) {}
    public record Asset(@Positive long checkinAssetId,@Min(0) int returnedQuantity,
        @NotBlank @Pattern(regexp="NEW|GOOD|FAIR|DAMAGED|MISSING") String condition,
        @NotBlank @Pattern(regexp="NATURAL_WEAR|PREEXISTING|TENANT|UNKNOWN|MISSING") String responsibility,
        @NotBlank @Size(max=500) String reference,@Size(max=1000) String note) {}
    public record Inspection(@NotNull @Min(0) Long version,@NotNull LocalDateTime actualAt,
        @DecimalMin("0") BigDecimal electricity,@DecimalMin("0") BigDecimal water,@Min(0) int keysReturned,
        boolean includeHandoverDay,boolean repairRequired,@NotBlank @Size(max=500) String reference,
        @Size(max=500) String absenceReference,@NotNull List<@Valid Asset> assets) {}
    public record ChargeRequest(@NotBlank @Size(max=100) String evidenceKey,
        @NotBlank @Pattern(regexp="DAMAGE|CLEANING|PENALTY|OTHER") String type,
        @NotBlank @Size(max=255) String description,@NotNull @DecimalMin("0.01") @Digits(integer=13,fraction=2) BigDecimal amount,
        @NotBlank @Size(max=500) String reference,@NotBlank @Size(max=1000) String reason,Long maintenanceId) {}
    public record ChargeDecision(boolean confirmed,@NotBlank @Size(max=1000) String reason) {}
    public record Approval(@NotNull @Min(0) Long version,@NotBlank @Size(min=64,max=64) String contentHash,
        @NotBlank @Size(max=500) String policyReference,@NotBlank @Size(max=1000) String reason,
        @NotBlank @Pattern(regexp="NONE|RETAIN_AS_BILLED") String creditTreatment) {}
    public record Confirmation(@Positive long version,@NotBlank @Size(min=64,max=64) String contentHash) {}
    public record Dispute(@NotBlank @Size(max=2000) String description) {}
    public record Resolution(@NotBlank @Size(max=2000) String reason,@NotBlank @Size(max=500) String reference) {}
    public record Preview(List<Charge> lines,List<String> credits,BigDecimal oldDebt,BigDecimal newCharges,
        BigDecimal deposit,BigDecimal deduction,BigDecimal refund,BigDecimal balanceDue,String content,String hash) {}
    private final JdbcClient db;
    private final DepositLedgerService deposits;
    private final RoomLifecycleGuard rooms;
    private final RentalLifecycleRepository lifecycle;
    private final MonthlyBillingService billing;
    @Transactional public String document(AuthenticatedUser p,long contract){var detail=detail(p,contract);var co=(Map<String,Object>)detail.get("checkout");if(co==null||detail.get("approved")==null)throw fail("SETTLEMENT_APPROVAL_REQUIRED","Chưa có bản quyết toán đã phê duyệt.");var version=(Map<String,Object>)detail.get("approved");return "BIÊN BẢN BÀN GIAO / HỒ SƠ THANH LÝ NỘI BỘ\nKhông phải chứng nhận chữ ký điện tử.\n"+version.get("content")+"\n\nTRẠNG THÁI THỰC TẾ\nCheckout: "+co.get("status")+"; bàn giao: "+co.get("actual_checkout_at")+"; giai đoạn: "+co.get("workflow_stage")+"\nNợ hiện tại: "+detail.get("currentDebt")+"; cọc còn giữ: "+detail.get("depositBalance")+"\nXác nhận: "+detail.get("confirmations")+"\nHoàn cọc: "+detail.get("refunds")+"\nChứng từ thực thu/chi và bù trừ: "+detail.get("transactions")+"\nLịch sử: "+detail.get("history");}
    public CheckoutSettlementService(JdbcClient db,DepositLedgerService deposits,RoomLifecycleGuard rooms){this.db=db;this.deposits=deposits;this.rooms=rooms;this.lifecycle=new RentalLifecycleRepository(db,rooms);this.billing=new MonthlyBillingService(db);}
    private List<Map<String,Object>> rows(String sql,long value){return db.sql(sql).param("id",value).query().listOfRows();}
    private Map<String,Object> contract(long c){return rows("SELECT c.*,c.agreed_monthly_rent monthly_rent,r.property_id,r.code room_code,p.owner_id FROM contracts c JOIN rooms r ON r.id=c.room_id JOIN properties p ON p.id=r.property_id WHERE c.id=:id",c).stream().findFirst().orElseThrow(()->fail("CONTRACT_NOT_FOUND","Không tìm thấy hợp đồng."));}
    private void accessContract(AuthenticatedUser p,Map<String,Object> c,boolean staff){if(p==null)throw denied();if(staff&&p.activeRole()==RoleCode.MANAGER)rooms.capability(p,id(c,"property_id"),com.thangit.boardinghouse.security.PropertyAuthorization.Capability.CONTRACT_APPROVE);switch(p.activeRole()){
        case OWNER,MANAGER -> rooms.access(p,id(c,"property_id"));
        case TENANT -> {if(staff||p.id()!=id(c,"tenant_id"))throw denied();}
        case ACCOUNTANT -> {if(staff||db.sql("SELECT COUNT(*) FROM accountant_property_assignments WHERE accountant_id=:user AND property_id=:property").param("user",p.id()).param("property",c.get("property_id")).query(Long.class).single()==0)throw denied();}
        default -> throw denied();}}
    private Map<String,Object> checkout(AuthenticatedUser p,long co,boolean staff){rooms.lockCheckout(co);var row=rows("SELECT * FROM rental_checkouts WHERE id=:id FOR UPDATE",co).stream().findFirst().orElseThrow(()->fail("CHECKOUT_NOT_FOUND","Không tìm thấy yêu cầu trả phòng."));accessContract(p,contract(id(row,"contract_id")),staff);return row;}
    private AuthException denied(){return new AuthException(HttpStatus.FORBIDDEN,"CHECKOUT_ACCESS_DENIED","Không có quyền thao tác hồ sơ trả phòng này.");}
    private void expected(Map<String,Object> co,long version){if(id(co,"version")!=version)throw fail("CHECKOUT_VERSION_CONFLICT","Hồ sơ đã thay đổi; cần tải lại.");}
    private void editable(Map<String,Object> co){if(co.get("settlement_applied_at")!=null||Set.of("COMPLETED","CANCELLED").contains(co.get("status")))throw fail("CHECKOUT_ALREADY_SETTLED","Hồ sơ đã quyết toán hoặc hủy; không được sửa nguồn.");}
    private void bump(long co){db.sql("UPDATE rental_checkouts SET version=version+1,approved_version_id=NULL,workflow_stage=CASE WHEN actual_checkout_at IS NOT NULL THEN 'HANDED_OVER_FINANCE_PENDING' WHEN inspection_at IS NULL THEN 'REQUESTED' ELSE 'INSPECTION' END WHERE id=:id").param("id",co).update();}
    private void history(long co,long actor,String event,String text){db.sql("INSERT INTO checkout_history(checkout_id,event_type,actor_id,description) VALUES(:id,:event,:actor,:text)").param("id",co).param("event",event).param("actor",actor).param("text",text.substring(0,Math.min(2000,text.length()))).update();}
    private void notify(Map<String,Object> c,String text){db.sql("INSERT INTO notifications(user_id,title,content,type,category) VALUES(:tenant,'Hồ sơ trả phòng',:text,'CONTRACT','CONTRACT'),(:owner,'Hồ sơ trả phòng',:text,'CONTRACT','CONTRACT')").param("tenant",c.get("tenant_id")).param("owner",c.get("owner_id")).param("text",text).update();}
    @Transactional public Created request(AuthenticatedUser p,RequestCheckout r){rooms.lockContract(r.contractId());var c=contract(r.contractId());accessContract(p,c,false);if(p.activeRole()==RoleCode.ACCOUNTANT)throw denied();if(r.requestedDate().isBefore(LocalDate.now())||r.requestedDate().isBefore(date(c.get("start_date"))))throw fail("CHECKOUT_DATE_INVALID","Ngày dự kiến không được ở quá khứ hoặc trước hợp đồng.");rooms.checkout(r.contractId(),null);if(lifecycle.hasCheckout(r.contractId()))throw fail("CHECKOUT_EXISTS","Đã có yêu cầu trả phòng đang hoạt động.");var result=lifecycle.requestCheckout("CO-"+UUID.randomUUID().toString().replace("-",""),r,lifecycle.contract(r.contractId()).orElseThrow(),p.id());onRequested(p,result.id());if(p.activeRole()==RoleCode.TENANT)db.sql("INSERT INTO contract_termination_requests(contract_id,tenant_id,expected_move_out_date,reason,contact_phone) SELECT :contract,:tenant,:date,:reason,tp.phone FROM tenant_profiles tp WHERE tp.id=:profile AND NOT EXISTS(SELECT 1 FROM contract_termination_requests WHERE contract_id=:contract AND status='PENDING')").param("contract",c.get("id")).param("tenant",p.id()).param("date",r.requestedDate()).param("reason",r.reason()).param("profile",c.get("tenant_profile_id")).update();return result;}
    public void onRequested(AuthenticatedUser p,long co){var row=checkout(p,co,false);var c=contract(id(row,"contract_id"));if(date(row.get("requested_date")).isBefore(LocalDate.now()))throw fail("CHECKOUT_DATE_INVALID","Ngày dự kiến không được ở quá khứ.");db.sql("UPDATE rental_checkouts SET request_source=:source,workflow_stage='REQUESTED' WHERE id=:id").param("source",p.activeRole()==RoleCode.TENANT?"TENANT":"STAFF").param("id",co).update();history(co,p.id(),"REQUESTED",p.activeRole()+"; "+row.get("reason")+"; chưa phải xác nhận bàn giao");notify(c,"Đã ghi nhận yêu cầu trả phòng hợp đồng "+c.get("code")+"; cần xác nhận lịch và kiểm kê.");}
    @Transactional public Map<String,Object> detail(AuthenticatedUser p,long contract){rooms.lockContract(contract);var c=contract(contract);accessContract(p,c,false);var result=new LinkedHashMap<String,Object>();result.put("contractId",contract);result.put("contractCode",c.get("code"));result.put("contractEnd",c.get("end_date"));result.put("noticeDays",c.get("notice_period_days"));var co=rows("SELECT * FROM rental_checkouts WHERE contract_id=:id ORDER BY id DESC LIMIT 1",contract).stream().findFirst().orElse(null);result.put("checkout",co);if(co==null)return result;long id=id(co,"id");result.put("initialAssets",rows("SELECT a.* FROM rental_checkin_assets a JOIN rental_checkins ci ON ci.id=a.checkin_id WHERE ci.contract_id=:id ORDER BY a.id",contract));result.put("initialKeys",rows("SELECT keys_cards_count,actual_checkin_at FROM rental_checkins WHERE contract_id=:id AND status='COMPLETED'",contract).stream().findFirst().map(x->x.get("keys_cards_count")).orElse(null));var inspectionVersion=inspectionVersion(id);result.put("inspectionVersion",inspectionVersion);result.put("inspectionConfirmations",inspectionVersion==null?List.of():rows("SELECT party,actor_id,confirmed_at FROM checkout_inspection_confirmations WHERE revision_id=:id ORDER BY id",id(inspectionVersion,"id")));result.put("inspection",rows("SELECT * FROM checkout_asset_inspections WHERE checkout_id=:id ORDER BY checkin_asset_id",id));result.put("charges",rows("SELECT * FROM checkout_verified_charges WHERE checkout_id=:id ORDER BY id",id));result.put("history",rows("SELECT * FROM checkout_history WHERE checkout_id=:id ORDER BY id DESC",id));result.put("disputes",rows("SELECT * FROM checkout_disputes WHERE checkout_id=:id ORDER BY id DESC",id));result.put("rates",rows("SELECT code,calculation_method,unit_price,unit FROM contract_utility_rates WHERE contract_id=:id ORDER BY code",contract));var approved=co.get("approved_version_id")==null?null:rows("SELECT * FROM checkout_settlement_versions WHERE id=:id",id(co,"approved_version_id")).getFirst();result.put("approved",approved);result.put("confirmations",approved==null?List.of():rows("SELECT party,actor_id,confirmed_at FROM checkout_confirmations WHERE version_id=:id ORDER BY id",id(approved,"id")));result.put("completionCharges",approved==null?List.of():completionCharges(id(approved,"id")));result.put("inspectionRevisions",rows("SELECT * FROM checkout_inspection_revisions WHERE checkout_id=:id ORDER BY id DESC",id));result.put("versions",rows("SELECT id,version,content_hash,created_at,created_by,reason FROM checkout_settlement_versions WHERE checkout_id=:id ORDER BY version DESC",id));
        var d=deposits.byContract(contract);result.put("depositId",d.get("id"));result.put("depositBalance",d.get("balance_amount"));result.put("refunds",rows("SELECT * FROM deposit_refund_requests WHERE checkout_id=:id ORDER BY id",id));result.put("transactions",rows("SELECT * FROM deposit_transactions WHERE deposit_id=:id ORDER BY id",id(d,"id")));result.put("currentDebt",db.sql("SELECT COALESCE(SUM(remaining_amount),0) FROM invoices WHERE contract_id=:id AND status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED')").param("id",contract).query(BigDecimal.class).single());result.put("currentFinancialStatus","COMPLETED".equals(co.get("status"))?"COMPLETED":openDisputes(id)?"DISPUTED":co.get("settlement_applied_at")==null?"NOT_SETTLED":money(result.get("currentDebt")).signum()==0&&money(d.get("balance_amount")).signum()==0?"FINANCE_SETTLED_AWAITING_CLOSE":co.get("financial_status"));result.put("timing",timing(c,co));if(co.get("inspection_at")!=null&&co.get("settlement_applied_at")==null)try{result.put("preview",previewInternal(co));}catch(AuthException e){result.put("previewError",e.getMessage());result.put("previewErrorCode",e.code());}return result;}
    private Map<String,Object> timing(Map<String,Object> c,Map<String,Object> co){long days=ChronoUnit.DAYS.between(date(co.get("created_at")),date(co.get("requested_date")));return Map.of("classification",date(co.get("requested_date")).isBefore(date(c.get("end_date")))?"EARLY":date(co.get("requested_date")).isAfter(date(c.get("end_date")))?"LATE":"ON_TIME","noticeGiven",days,"noticeRequired",c.get("notice_period_days"),"shortNotice",days<id(c,"notice_period_days"));}
    @Transactional public void schedule(AuthenticatedUser p,long id,Schedule r){var co=checkout(p,id,false);if(p.activeRole()==RoleCode.ACCOUNTANT)throw denied();editable(co);expected(co,r.version());if(co.get("actual_checkout_at")!=null)throw fail("CHECKOUT_ALREADY_HANDED_OVER","Đã bàn giao thực tế; không đổi lịch.");if(r.date().isBefore(LocalDate.now()))throw fail("CHECKOUT_DATE_INVALID","Lịch mới không được ở quá khứ.");db.sql("UPDATE rental_checkouts SET requested_date=:date,inspection_at=NULL,inspected_by=NULL WHERE id=:id").param("date",r.date()).param("id",id).update();bump(id);history(id,p.id(),"RESCHEDULED","Previous date="+co.get("requested_date")+"; "+r);notify(contract(id(co,"contract_id")),"Đã đổi lịch trả phòng; các xác nhận cũ cần được kiểm tra lại.");}
    @Transactional public void approveSchedule(AuthenticatedUser p,long id,Schedule r){var co=checkout(p,id,true);editable(co);if(co.get("actual_checkout_at")!=null)throw fail("CHECKOUT_HANDOVER_LOCKED","Lịch bàn giao đã được chốt.");expected(co,r.version());if(r.date().isBefore(LocalDate.now()))throw fail("CHECKOUT_DATE_INVALID","Ngày xác nhận không hợp lệ.");db.sql("UPDATE rental_checkouts SET confirmed_date=:date,workflow_stage='APPROVED',version=version+1,approved_version_id=NULL WHERE id=:id").param("date",r.date()).param("id",id).update();history(id,p.id(),"SCHEDULE_APPROVED",r.toString()+"; đã kiểm tra báo trước/thời hạn, không tự phạt hoặc mất cọc");}
    @Transactional public void cancel(AuthenticatedUser p,long id,VersionedReason r){var co=checkout(p,id,false);if(p.activeRole()==RoleCode.ACCOUNTANT)throw denied();expected(co,r.version());editable(co);if(co.get("actual_checkout_at")!=null)throw fail("CHECKOUT_ALREADY_HANDED_OVER","Không hủy sau khi đã bàn giao thực tế.");db.sql("UPDATE rental_checkouts SET status='CANCELLED',workflow_stage='CANCELLED',version=version+1,approved_version_id=NULL WHERE id=:id").param("id",id).update();var c=contract(id(co,"contract_id"));rooms.transition(id(c,"room_id"),"OCCUPIED","Rút yêu cầu trả phòng: "+r.reason(),p.id());db.sql("UPDATE contract_termination_requests SET status='CANCELLED' WHERE contract_id=:id AND status='PENDING'").param("id",c.get("id")).update();history(id,p.id(),"CANCELLED",r.reason());notify(c,"Đã rút yêu cầu trả phòng; quyền cư trú tiếp tục theo hợp đồng.");}
    @Transactional public void inspect(AuthenticatedUser p,long id,Inspection r){var co=checkout(p,id,true);editable(co);expected(co,r.version());if(co.get("actual_checkout_at")!=null)throw fail("CHECKOUT_HANDOVER_LOCKED","Physical handover evidence is immutable; request an audited correction");if(co.get("confirmed_date")==null)throw fail("CHECKOUT_SCHEDULE_REQUIRED","Cần xác nhận lịch trước kiểm kê.");var c=contract(id(co,"contract_id"));if(r.actualAt().toLocalDate().isBefore(date(c.get("start_date")))||r.actualAt().isAfter(LocalDateTime.now().plusMinutes(5)))throw fail("CHECKOUT_DATE_INVALID","Ngày giờ kiểm kê/bàn giao không hợp lệ.");var assets=rows("SELECT a.* FROM rental_checkin_assets a JOIN rental_checkins ci ON ci.id=a.checkin_id WHERE ci.contract_id=:id ORDER BY a.id",id(c,"id"));Set<Long> seen=new HashSet<>();for(var asset:r.assets()){var original=assets.stream().filter(a->id(a,"id")==asset.checkinAssetId()).findFirst().orElseThrow(()->fail("CHECKOUT_ASSET_INVALID","Tài sản không thuộc biên bản nhận phòng."));if(!seen.add(asset.checkinAssetId())||asset.returnedQuantity()>id(original,"quantity"))throw fail("CHECKOUT_ASSET_INVALID","Tài sản lặp hoặc số lượng trả vượt số nhận.");}if(seen.size()!=assets.size())throw fail("CHECKOUT_INVENTORY_INCOMPLETE","Cần đối chiếu đủ snapshot tài sản khi nhận phòng.");var keys=rows("SELECT keys_cards_count,actual_checkin_at FROM rental_checkins WHERE contract_id=:id AND status='COMPLETED'",id(c,"id"));if(keys.isEmpty())throw fail("CHECKIN_EVIDENCE_REQUIRED","Thiếu biên bản nhận phòng để đối chiếu.");
        var receivedAt=db.sql("SELECT actual_checkin_at FROM rental_checkins WHERE contract_id=:id AND status='COMPLETED'").param("id",id(c,"id")).query(LocalDateTime.class).optional().orElseThrow(()->fail("CHECKIN_EVIDENCE_REQUIRED","Missing actual check-in time"));if(r.actualAt().isBefore(receivedAt))throw fail("CHECKOUT_DATE_INVALID","Handover cannot precede actual check-in");
        db.sql("DELETE FROM checkout_asset_inspections WHERE checkout_id=:id").param("id",id).update();for(var a:r.assets())db.sql("INSERT INTO checkout_asset_inspections(checkout_id,checkin_asset_id,returned_quantity,returned_condition,responsibility,evidence_reference,note) VALUES(:id,:asset,:quantity,:condition,:responsibility,:reference,:note)").param("id",id).param("asset",a.checkinAssetId()).param("quantity",a.returnedQuantity()).param("condition",a.condition()).param("responsibility",a.responsibility()).param("reference",a.reference()).param("note",a.note()).update();db.sql("UPDATE rental_checkouts SET inspection_at=:at,inspected_by=:actor,final_electricity_reading=:electricity,final_water_reading=:water,keys_returned=:keys,include_handover_day=:include,repair_required=:repair,handover_reference=:reference,absence_reference=:absence WHERE id=:id").param("at",r.actualAt()).param("actor",p.id()).param("electricity",r.electricity()).param("water",r.water()).param("keys",r.keysReturned()).param("include",r.includeHandoverDay()).param("repair",r.repairRequired()||r.assets().stream().anyMatch(a->Set.of("DAMAGED","MISSING").contains(a.condition()))||r.keysReturned()<id(keys.getFirst(),"keys_cards_count")).param("reference",r.reference()).param("absence",r.absenceReference()==null||r.absenceReference().isBlank()?null:r.absenceReference()).param("id",id).update();bump(id);db.sql("INSERT INTO checkout_inspection_revisions(checkout_id,version,content,content_hash,actor_id) SELECT id,version,:content,:hash,:actor FROM rental_checkouts WHERE id=:id").param("content",r.toString()).param("hash",hash(r.toString())).param("actor",p.id()).param("id",id).update();db.sql("INSERT INTO checkout_inspection_confirmations(revision_id,party,actor_id) SELECT id,'LANDLORD',:actor FROM checkout_inspection_revisions WHERE checkout_id=:id AND version=(SELECT version FROM rental_checkouts WHERE id=:id)").param("actor",p.id()).param("id",id).update();history(id,p.id(),"INSPECTION_RECORDED",r.toString());}
    @Transactional public long proposeCharge(AuthenticatedUser p,long id,ChargeRequest r){var co=checkout(p,id,true);editable(co);var c=contract(id(co,"contract_id"));if(r.maintenanceId()!=null&&db.sql("SELECT COUNT(*) FROM maintenance_requests WHERE id=:maintenance AND room_id=:room").param("maintenance",r.maintenanceId()).param("room",c.get("room_id")).query(Long.class).single()!=1)throw fail("MAINTENANCE_SCOPE_INVALID","Hồ sơ kỹ thuật không thuộc phòng.");GeneratedKeyHolder key=new GeneratedKeyHolder();db.sql("INSERT INTO checkout_verified_charges(checkout_id,evidence_key,charge_type,description,amount,evidence_reference,reason,created_by,maintenance_id) VALUES(:id,:key,:type,:description,:amount,:reference,:reason,:actor,:maintenance)").param("id",id).param("key",r.evidenceKey()).param("type",r.type()).param("description",r.description()).param("amount",r.amount()).param("reference",r.reference()).param("reason",r.reason()).param("actor",p.id()).param("maintenance",r.maintenanceId()).update(key,"id");bump(id);history(id,p.id(),"CHARGE_PROPOSED",r.toString());return key.getKey().longValue();}
    @Transactional public void decideCharge(AuthenticatedUser p,long coId,long charge,ChargeDecision r){var co=checkout(p,coId,true);editable(co);var row=db.sql("SELECT * FROM checkout_verified_charges WHERE id=:id AND checkout_id=:checkout FOR UPDATE").param("id",charge).param("checkout",coId).query().listOfRows().stream().findFirst().orElseThrow(()->fail("CHECKOUT_CHARGE_NOT_FOUND","Không tìm thấy khoản đề xuất."));if(!"PROPOSED".equals(row.get("status")))throw fail("CHARGE_ALREADY_REVIEWED","Khoản này đã được kiểm tra.");if(r.confirmed()&&row.get("maintenance_id")!=null&&db.sql("SELECT COUNT(*) FROM invoice_items x JOIN invoices i ON i.id=x.invoice_id WHERE x.source_type='MAINTENANCE' AND x.source_id=:id AND i.status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED')").param("id",row.get("maintenance_id")).query(Long.class).single()>0)throw fail("CHARGE_ALREADY_BILLED","Chi phí kỹ thuật đã được lập hóa đơn.");db.sql("UPDATE checkout_verified_charges SET status=:status,reviewed_by=:actor WHERE id=:id").param("status",r.confirmed()?"CONFIRMED":"REJECTED").param("actor",p.id()).param("id",charge).update();bump(coId);history(coId,p.id(),"CHARGE_REVIEWED",charge+"; "+r);}
    private String key(Charge x){return x.type()+"|"+("SERVICE".equals(x.type())?x.sourceId():"");}
    private Preview previewInternal(Map<String,Object> co){if(co.get("inspection_at")==null)throw fail("CHECKOUT_INSPECTION_REQUIRED","Chưa có kiểm kê và chỉ số bàn giao.");long contract=id(co,"contract_id");var c=contract(contract);BigDecimal oldDebt=deposits.settlementDebt(contract),deposit=deposits.held(contract);if(db.sql("SELECT COUNT(*) FROM invoice_balance_reconciliation WHERE contract_id=:id").param("id",contract).query(Long.class).single()>0)throw fail("DEBT_RECONCILIATION_REQUIRED","Số dư hóa đơn lịch sử cần đối soát.");if(db.sql("SELECT COUNT(*) FROM tenant_invoice_review_requests WHERE invoice_id IN (SELECT id FROM invoices WHERE contract_id=:id) AND status IN ('PENDING','IN_REVIEW')").param("id",contract).query(Long.class).single()>0)throw fail("CHECKOUT_INVOICE_DISPUTED","Còn yêu cầu rà soát hóa đơn chưa giải quyết.");
        LocalDate at=date(co.get("inspection_at")),end=Boolean.TRUE.equals(co.get("include_handover_day"))?at.plusDays(1):at;var ci=rows("SELECT actual_checkin_at FROM rental_checkins WHERE contract_id=:id AND status='COMPLETED'",contract);if(ci.isEmpty())throw fail("CHECKIN_EVIDENCE_REQUIRED","Chưa có bàn giao nhận phòng.");LocalDate start=date(ci.getFirst().get("actual_checkin_at"));LocalDate last=at.withDayOfMonth(1);var items=new ArrayList<Charge>();var credits=new ArrayList<String>();StringBuilder content=new StringBuilder("QUYẾT TOÁN VÀ BÀN GIAO NỘI BỘ\n");content.append("contract=").append(contract).append("; originalEnd=").append(c.get("end_date")).append("; inspection=").append(co.get("inspection_at")).append("; includeHandoverDay=").append(co.get("include_handover_day")).append("; keys=").append(co.get("keys_returned")).append("; repair=").append(co.get("repair_required")).append("; evidence=").append(co.get("handover_reference")).append("; absence=").append(co.get("absence_reference")).append('\n');
        for(LocalDate month=start.withDayOfMonth(1);!month.isAfter(last);month=month.plusMonths(1)){var issued=db.sql("SELECT * FROM invoices WHERE contract_id=:id AND billing_period=:period AND status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED') ORDER BY id").param("id",contract).param("period",month).query().listOfRows();if(month.isBefore(last)&&issued.stream().anyMatch(i->"RENTAL".equals(i.get("invoice_kind"))))continue;if(!issued.isEmpty()&&issued.stream().anyMatch(i->money(i.get("discount_amount")).signum()>0||Boolean.TRUE.equals(i.get("has_adjustment"))))throw fail("CHECKOUT_ALLOCATION_REVIEW_REQUIRED","Hóa đơn có giảm giá/điều chỉnh tổng; cần đối soát phân bổ từng khoản trước quyết toán.");var request=new SaveInvoice(id(c,"room_id"),contract,month.toString().substring(0,7),month,month.plusMonths(1).minusDays(1),LocalDate.now(),LocalDate.now(),List.of(),BigDecimal.ZERO,false,null,"SAVE_DRAFT",null);Plan plan=month.equals(last)?billing.finalPeriod(request,c,end,(BigDecimal)co.get("final_electricity_reading"),(BigDecimal)co.get("final_water_reading")):billing.calculate(request,c);Map<String,BigDecimal> billed=new HashMap<>();for(var i:issued)for(var item:rows("SELECT item_type,source_type,source_id,amount FROM invoice_items WHERE invoice_id=:id ORDER BY id",id(i,"id"))){String type=item.get("item_type").toString();String k=type+"|"+("SERVICE".equals(type)?item.get("source_id"):"");billed.merge(k,money(item.get("amount")),BigDecimal::add);}for(var x:plan.items()){BigDecimal delta=x.amount().subtract(billed.getOrDefault(key(x),BigDecimal.ZERO));if(delta.signum()<0){credits.add(month+"; "+x.name()+"; cần đối soát khoản đã tính dư "+delta.abs().toPlainString());continue;}if(delta.signum()==0)continue;BigDecimal qty=x.price().signum()==0?BigDecimal.ONE:delta.divide(x.price(),8,RoundingMode.HALF_UP);items.add(new Charge(x.type(),x.name(),month+"; "+x.description()+"; chỉ phần chưa lập hóa đơn",qty,x.unit(),x.price(),delta,x.source(),x.sourceId()));}content.append("period=").append(month).append("; source=").append(plan.content()).append("; issued=").append(issued.stream().map(i->new TreeMap<>(i)).toList()).append('\n');}
        for(var extra:rows("SELECT * FROM checkout_verified_charges WHERE checkout_id=:id AND status='CONFIRMED' ORDER BY id",id(co,"id")))items.add(new Charge(extra.get("charge_type").toString(),extra.get("description").toString(),extra.get("reason")+"; chứng từ "+extra.get("evidence_reference"),BigDecimal.ONE,"khoản",money(extra.get("amount")),money(extra.get("amount")),"CHECKOUT_VERIFIED_CHARGE",id(extra,"id")));
        var allInvoices=rows("SELECT id,code,version,status,total_amount,paid_amount,remaining_amount,billing_period FROM invoices WHERE contract_id=:id AND status NOT IN ('DRAFT','PENDING_REVIEW','CANCELLED') ORDER BY id",contract);var depositSource=deposits.byContract(contract);content.append("depositSource=").append(depositSource.get("id")).append("; version=").append(depositSource.get("version")).append("; required=").append(depositSource.get("required_amount")).append("\n");content.append("initialAssets=").append(rows("SELECT a.* FROM rental_checkin_assets a JOIN rental_checkins ci ON ci.id=a.checkin_id WHERE ci.contract_id=:id ORDER BY a.id",contract).stream().map(TreeMap::new).toList()).append("\n");content.append("invoices=").append(allInvoices.stream().map(i->new TreeMap<>(i)).toList()).append("\nassets=").append(rows("SELECT * FROM checkout_asset_inspections WHERE checkout_id=:id ORDER BY checkin_asset_id",id(co,"id")).stream().map(TreeMap::new).toList()).append("\nverifiedCharges=").append(rows("SELECT * FROM checkout_verified_charges WHERE checkout_id=:id ORDER BY id",id(co,"id")).stream().map(TreeMap::new).toList()).append("\ncredits=").append(credits).append("\ndeposit=").append(deposit.toPlainString()).append("; oldDebt=").append(oldDebt.toPlainString()).append("\nlines=").append(items);
        BigDecimal charges=items.stream().map(Charge::amount).reduce(BigDecimal.ZERO,BigDecimal::add),total=oldDebt.add(charges),deduction=deposit.min(total);return new Preview(List.copyOf(items),List.copyOf(credits),oldDebt,charges,deposit,deduction,deposit.subtract(deduction),total.subtract(deduction),content.toString(),hash(content.toString()));}
    @Transactional public Preview preview(AuthenticatedUser p,long id){var co=checkout(p,id,false);return previewInternal(co);}
    @Transactional public void approve(AuthenticatedUser p,long id,Approval r){var co=checkout(p,id,true);editable(co);expected(co,r.version());if(openDisputes(id))throw fail("CHECKOUT_DISPUTED","Cần xử lý phản hồi trước khi phê duyệt.");var plan=previewInternal(co);if(!r.contentHash().equals(plan.hash()))throw fail("SETTLEMENT_SOURCE_CHANGED","Nguồn quyết toán đã thay đổi; xem lại bảng mới.");if(!plan.credits().isEmpty()&&!"RETAIN_AS_BILLED".equals(r.creditTreatment()))throw fail("CHECKOUT_CREDIT_REVIEW_REQUIRED","Có khoản đã thu/tính dư; cần điều chỉnh hoặc thỏa thuận riêng, không tự bỏ qua.");long version=id(co,"version")+1;String content=plan.content()+"\npolicyReference="+r.policyReference()+"; reason="+r.reason()+"; creditTreatment="+r.creditTreatment();GeneratedKeyHolder key=new GeneratedKeyHolder();db.sql("INSERT INTO checkout_settlement_versions(checkout_id,version,content,content_hash,base_hash,created_by,policy_reference,reason,credit_treatment,old_debt,new_charges,deposit_held,deduction,refund_due,balance_due) VALUES(:id,:version,:content,:hash,:base,:actor,:reference,:reason,:credit,:oldDebt,:newCharges,:deposit,:deduction,:refund,:due)").param("id",id).param("version",version).param("content",content).param("hash",hash(content)).param("base",plan.hash()).param("actor",p.id()).param("reference",r.policyReference()).param("reason",r.reason()).param("credit",r.creditTreatment()).param("oldDebt",plan.oldDebt()).param("newCharges",plan.newCharges()).param("deposit",plan.deposit()).param("deduction",plan.deduction()).param("refund",plan.refund()).param("due",plan.balanceDue()).update(key,"id");long approved=key.getKey().longValue();for(var line:plan.lines())db.sql("INSERT INTO checkout_settlement_lines(version_id,item_type,name,description,quantity,unit,unit_price,amount,source_type,source_id) VALUES(:id,:type,:name,:description,:qty,:unit,:price,:amount,:source,:sourceId)").param("id",approved).param("type",line.type()).param("name",line.name()).param("description",line.description().substring(0,Math.min(1000,line.description().length()))).param("qty",line.quantity()).param("unit",line.unit()).param("price",line.price()).param("amount",line.amount()).param("source",line.source()).param("sourceId",line.sourceId()).update();db.sql("INSERT INTO checkout_confirmations(version_id,party,actor_id) VALUES(:id,'LANDLORD',:actor)").param("id",approved).param("actor",p.id()).update();db.sql("UPDATE rental_checkouts SET approved_version_id=:approved,version=:version,workflow_stage='SETTLEMENT_APPROVED' WHERE id=:id").param("approved",approved).param("version",version).param("id",id).update();history(id,p.id(),"SETTLEMENT_APPROVED",r.toString());notify(contract(id(co,"contract_id")),"Quyết toán đã được bên cho thuê phê duyệt theo phiên bản; người thuê xem và phản hồi/xác nhận.");}
    @Transactional public void confirm(AuthenticatedUser p,long id,Confirmation r){var co=checkout(p,id,false);var c=contract(id(co,"contract_id"));if(p.activeRole()!=RoleCode.TENANT||p.id()!=id(c,"tenant_id"))throw denied();editable(co);var version=approved(co);if(id(version,"version")!=r.version()||!r.contentHash().equals(version.get("content_hash")))throw fail("SETTLEMENT_VERSION_CONFLICT","Cần đọc và xác nhận đúng phiên bản hiện tại.");if(openDisputes(id))throw fail("CHECKOUT_DISPUTED","Đang có phản hồi cần xử lý.");if(!version.get("base_hash").equals(previewInternal(co).hash()))throw fail("SETTLEMENT_SOURCE_CHANGED","Số liệu đã thay đổi; cần phê duyệt lại.");db.sql("INSERT IGNORE INTO checkout_confirmations(version_id,party,actor_id) VALUES(:id,'TENANT',:actor)").param("id",version.get("id")).param("actor",p.id()).update();history(id,p.id(),"TENANT_CONFIRMED","Xác nhận nội bộ quyết toán/bàn giao phiên bản "+r.version());}
    private Map<String,Object> approved(Map<String,Object> co){if(co.get("approved_version_id")==null)throw fail("SETTLEMENT_APPROVAL_REQUIRED","Cần phê duyệt bảng quyết toán theo phiên bản.");return rows("SELECT * FROM checkout_settlement_versions WHERE id=:id",id(co,"approved_version_id")).getFirst();}
    private boolean openDisputes(long co){return db.sql("SELECT COUNT(*) FROM checkout_disputes WHERE checkout_id=:id AND status='OPEN'").param("id",co).query(Long.class).single()>0;}
    private void handoverEvidence(Map<String,Object> co,Map<String,Object> v){boolean tenant=db.sql("SELECT COUNT(*) FROM checkout_confirmations WHERE version_id=:id AND party='TENANT'").param("id",v.get("id")).query(Long.class).single()>0;if(!tenant&&(co.get("absence_reference")==null||"RETAIN_AS_BILLED".equals(v.get("credit_treatment"))))throw fail("CHECKOUT_HANDOVER_NOT_CONFIRMED","Chưa có xác nhận người thuê hoặc hồ sơ xử lý vắng mặt hợp lệ; không tự ký thay.");if(((LocalDateTime)co.get("inspection_at")).isAfter(LocalDateTime.now()))throw fail("CHECKOUT_DATE_INVALID","Chưa đến ngày bàn giao thực tế.");}
    public void requireApproved(AuthenticatedUser p,long id,CompleteCheckout r){var co=checkout(p,id,true);editable(co);expected(co,r.version()==null?-1:r.version());if(openDisputes(id))throw fail("CHECKOUT_DISPUTED","Còn phản hồi chưa giải quyết.");var v=approved(co);var plan=previewInternal(co);if(!v.get("base_hash").equals(plan.hash()))throw fail("SETTLEMENT_SOURCE_CHANGED","Công nợ/cọc hoặc dữ liệu kiểm kê đã thay đổi; cần phê duyệt lại.");handoverEvidence(co,v);if(!r.actualDate().equals(date(co.get("inspection_at")))||!Objects.equals(r.finalElectricityReading(),co.get("final_electricity_reading"))&&!same(r.finalElectricityReading(),co.get("final_electricity_reading"))||!same(r.finalWaterReading(),co.get("final_water_reading")))throw fail("CHECKOUT_HANDOVER_CHANGED","Ngày hoặc chỉ số không khớp biên bản đã xác nhận.");var expected=completionCharges(id(v,"id"));if(!sameCharges(expected,r.charges()))throw fail("SETTLEMENT_CHARGES_CHANGED","Không nhận phí nhập tay khác bảng quyết toán đã phê duyệt.");}
    private boolean same(BigDecimal a,Object b){return a==null?b==null:b!=null&&a.compareTo(money(b))==0;}
    private Map<String,Object> inspectionVersion(long co){return rows("SELECT * FROM checkout_inspection_revisions WHERE checkout_id=:id ORDER BY version DESC LIMIT 1",co).stream().findFirst().orElse(null);}
    @Transactional public void confirmInspection(AuthenticatedUser p,long id,Confirmation r){var co=checkout(p,id,false);editable(co);if(p.activeRole()!=RoleCode.TENANT)throw denied();var v=inspectionVersion(id);if(co.get("inspection_at")==null||v==null||id(v,"version")!=r.version()||!r.contentHash().equals(v.get("content_hash")))throw fail("INSPECTION_VERSION_CONFLICT","Cần xem và xác nhận đúng bản kiểm kê hiện tại.");db.sql("INSERT IGNORE INTO checkout_inspection_confirmations(revision_id,party,actor_id) VALUES(:id,'TENANT',:actor)").param("id",v.get("id")).param("actor",p.id()).update();history(id,p.id(),"INSPECTION_CONFIRMED","Người thuê xác nhận kiểm kê/bàn giao, không mặc định chấp nhận các khoản tiền.");}
    @Transactional public void handover(AuthenticatedUser p,long id,VersionedReason r){var co=checkout(p,id,true);editable(co);expected(co,r.version());if(co.get("actual_checkout_at")!=null)throw fail("CHECKOUT_ALREADY_HANDED_OVER","Đã ghi nhận bàn giao; không chuyển trạng thái phòng lần nữa.");var v=inspectionVersion(id);if(co.get("inspection_at")==null||v==null)throw fail("CHECKOUT_INSPECTION_REQUIRED","Thiếu biên bản kiểm kê.");boolean tenant=db.sql("SELECT COUNT(*) FROM checkout_inspection_confirmations WHERE revision_id=:id AND party='TENANT'").param("id",v.get("id")).query(Long.class).single()>0;if(!tenant&&co.get("absence_reference")==null)throw fail("CHECKOUT_HANDOVER_NOT_CONFIRMED","Cần xác nhận kiểm kê của người thuê hoặc căn cứ xử lý vắng mặt.");if(((LocalDateTime)co.get("inspection_at")).isAfter(LocalDateTime.now()))throw fail("CHECKOUT_DATE_INVALID","Chưa đến ngày giờ bàn giao thực tế.");rooms.checkout(id(co,"contract_id"),date(co.get("inspection_at")));var operational=lifecycle.checkout(id).orElseThrow();db.sql("UPDATE rental_checkouts SET actual_checkout_at=inspection_at,status='SETTLEMENT',workflow_stage='HANDED_OVER_FINANCE_PENDING',financial_status='REVIEW_PENDING',version=version+1 WHERE id=:id").param("id",id).update();lifecycle.finishCheckout(operational,new CompleteCheckout(date(co.get("inspection_at")),(BigDecimal)co.get("final_electricity_reading"),(BigDecimal)co.get("final_water_reading"),List.of(),r.reason(),versionOf(co)),p.id());maintenance(co,p);history(id,p.id(),"PHYSICAL_HANDOVER","Đã kết thúc chiếm dụng theo kiểm kê; chưa bù trừ cọc/chưa đóng tài chính. "+r.reason());notify(contract(id(co,"contract_id")),"Đã ghi nhận bàn giao phòng; quyết toán và các khoản thu/hoàn vẫn được theo dõi riêng.");}
    private long versionOf(Map<String,Object> co){return id(co,"version");}
    private void maintenance(Map<String,Object> co,AuthenticatedUser p){var c=contract(id(co,"contract_id"));boolean repair=Boolean.TRUE.equals(co.get("repair_required"))||db.sql("SELECT COUNT(*) FROM checkout_verified_charges WHERE checkout_id=:id AND charge_type='DAMAGE' AND status='CONFIRMED'").param("id",co.get("id")).query(Long.class).single()>0;if(repair)db.sql("INSERT INTO maintenance_requests(property_id,room_id,code,title,issue_type,status,priority,description,reporter_id,reporter_type,source,created_by,cost_responsibility) SELECT :property,:room,:code,'Kiểm tra/sửa chữa sau bàn giao','OTHER','NEW','NORMAL',:description,:actor,'ADMIN','CHECKOUT',:actor,'OWNER' WHERE NOT EXISTS(SELECT 1 FROM maintenance_requests WHERE code=:code)").param("property",c.get("property_id")).param("room",c.get("room_id")).param("code","CO-MAINT-"+co.get("id")).param("description","Theo kiểm kê checkout #"+co.get("id")+"; "+co.get("handover_reference")+". Không tự tính thêm tiền người thuê.").param("actor",p.id()).update();}
    private boolean sameCharges(List<CheckoutCharge> expected,List<CheckoutCharge> actual){if(actual==null||actual.size()!=expected.size())return false;for(int i=0;i<expected.size();i++){var a=expected.get(i);var b=actual.get(i);if(!a.chargeType().equals(b.chargeType())||!a.description().equals(b.description())||a.amount().compareTo(b.amount())!=0)return false;}return true;}
    public List<CheckoutCharge> completionCharges(long version){return rows("SELECT item_type,name,amount FROM checkout_settlement_lines WHERE version_id=:id ORDER BY id",version).stream().map(x->new CheckoutCharge(Set.of("ELECTRICITY","WATER").contains(x.get("item_type"))?"UTILITY":Set.of("DAMAGE","CLEANING","PENALTY").contains(x.get("item_type"))?x.get("item_type").toString():"OTHER",x.get("name").toString(),money(x.get("amount")))).toList();}
    @Transactional public long dispute(AuthenticatedUser p,long id,Dispute r){var co=checkout(p,id,false);if(p.activeRole()==RoleCode.ACCOUNTANT)throw denied();if("COMPLETED".equals(co.get("status")))throw fail("CHECKOUT_CLOSED_REVIEW_REQUIRED","Hồ sơ đã đóng; cần mở lại theo quy trình đối soát.");GeneratedKeyHolder key=new GeneratedKeyHolder();db.sql("INSERT INTO checkout_disputes(checkout_id,version_id,description,created_by) VALUES(:id,:version,:description,:actor)").param("id",id).param("version",co.get("approved_version_id")).param("description",r.description()).param("actor",p.id()).update(key,"id");history(id,p.id(),"DISPUTED",r.description());notify(contract(id(co,"contract_id")),"Có phản hồi về quyết toán; tạm dừng phê duyệt/đóng hồ sơ.");return key.getKey().longValue();}
    @Transactional public void resolve(AuthenticatedUser p,long coId,long dispute,Resolution r){var co=checkout(p,coId,true);int changed=db.sql("UPDATE checkout_disputes SET status='RESOLVED',resolution=:reason,resolution_reference=:reference,resolved_by=:actor,resolved_at=NOW(6) WHERE id=:id AND checkout_id=:checkout AND status='OPEN'").param("reason",r.reason()).param("reference",r.reference()).param("actor",p.id()).param("id",dispute).param("checkout",coId).update();if(changed!=1)throw fail("DISPUTE_ALREADY_RESOLVED","Phản hồi không còn chờ xử lý.");if(co.get("settlement_applied_at")==null)bump(coId);else db.sql("UPDATE rental_checkouts SET version=version+1 WHERE id=:id").param("id",coId).update();history(coId,p.id(),"DISPUTE_RESOLVED",dispute+"; "+r);}
    public void applied(AuthenticatedUser p,long id){var co=checkout(p,id,true);var v=approved(co);var invoices=db.sql("SELECT id FROM invoices WHERE code=:code AND invoice_kind='SETTLEMENT'").param("code","QT-"+id).query(Long.class).list();if(!invoices.isEmpty()){long invoice=invoices.getFirst();db.sql("DELETE FROM invoice_items WHERE invoice_id=:id").param("id",invoice).update();db.sql("INSERT INTO invoice_items(invoice_id,item_type,name,description,quantity,unit,unit_price,amount,source_type,source_id) SELECT :invoice,item_type,name,description,quantity,unit,unit_price,amount,'CHECKOUT_FINAL',id FROM checkout_settlement_lines WHERE version_id=:version ORDER BY id").param("invoice",invoice).param("version",v.get("id")).update();db.sql("UPDATE invoices SET calculation_snapshot=:content,calculation_hash=:hash WHERE id=:id").param("content",v.get("content")).param("hash",v.get("content_hash")).param("id",invoice).update();db.sql("INSERT INTO invoice_history(invoice_id,action,previous_status,new_status,reason,performed_by) VALUES(:id,'CHECKOUT_SETTLEMENT',NULL,'ISSUED',:reason,:actor)").param("id",invoice).param("reason","Theo quyết toán checkout #"+id+" phiên bản "+v.get("version")).param("actor",p.id()).update();}db.sql("UPDATE rental_checkouts SET workflow_stage='PENDING_FINANCIAL_COMPLETION' WHERE id=:id").param("id",id).update();db.sql("UPDATE contract_termination_requests SET status='APPROVED' WHERE contract_id=:id AND status='PENDING'").param("id",co.get("contract_id")).update();maintenance(co,p);history(id,p.id(),"HANDED_OVER_AND_SETTLED","Đã bàn giao thực tế và bù trừ theo phiên bản "+v.get("version")+"; còn phải thu/hoàn được theo dõi riêng.");notify(contract(id(co,"contract_id")),"Đã ghi nhận bàn giao phòng; thu/hoàn tiền và đóng hồ sơ tài chính được theo dõi riêng.");}
}
